@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700;800&family=Nunito:wght@700;800;900&display=swap');
:root{--ink:#382b32;--muted:#9a8b8b;--coral:#ff6e59;--orange:#ffad49;--cream:#fff8ed;--pink:#fff0eb;--green:#4fae7a;--line:#f0e5d9;--shadow:0 12px 30px #4f342014;font-family:'DM Sans',sans-serif;color:var(--ink);font-synthesis:none}*{box-sizing:border-box}body{margin:0;background:#fffaf4;min-height:100vh}.app-shell{max-width:1440px;margin:auto;min-height:100vh;padding-bottom:34px}.topbar{height:88px;padding:0 clamp(20px,5vw,76px);display:flex;align-items:center;justify-content:space-between;background:#fffaf4;position:relative;z-index:5}.brand{border:0;background:none;display:flex;align-items:center;gap:12px;color:var(--ink);text-align:left;cursor:pointer}.brand-mark{width:48px;height:48px;border-radius:16px;background:#ffe4a9;display:grid;place-items:center;font-size:26px;box-shadow:inset 0 -3px #f4cf84}.brand-name{font:900 20px Nunito,sans-serif;line-height:1}.brand-name b{color:var(--coral)}.brand-name small{display:block;color:#a89a92;font:800 8px 'DM Sans';letter-spacing:1.55px;margin-top:6px}.wallet{display:flex;gap:10px}.wallet-pill{height:40px;padding:4px 8px 4px 12px;min-width:98px;border-radius:22px;display:flex;align-items:center;gap:7px;box-shadow:0 3px 0 #e8dfd6;font-size:15px}.coin-pill{background:#fff0c8}.gem-pill{background:#e8f4ff}.plus{border:0;border-radius:50%;width:25px;height:25px;font-size:19px;line-height:20px;font-weight:800;background:white;color:#7a6350;cursor:pointer;margin-left:auto}.avatar-button{width:44px;height:44px;border:3px solid white;box-shadow:0 3px 10px #60442620;border-radius:50%;background:#ffdfca;font-size:23px;position:relative}.avatar-button i{position:absolute;background:#53c67c;border:2px solid white;width:12px;height:12px;border-radius:50%;right:-2px;bottom:0}.bottom-nav{display:none}.screen{padding:10px clamp(20px,5vw,76px) 60px;animation:fadein .24s ease}@keyframes fadein{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:none}}.eyebrow{font-size:10px;letter-spacing:2px;color:#b29c8c;font-weight:800}.section-title{font:900 28px Nunito,sans-serif;margin:4px 0}.home-grid{display:grid;grid-template-columns:1fr 320px;gap:22px;margin-top:20px}.hero-card{min-height:405px;border-radius:28px;background:linear-gradient(120deg,#ffdfb4 0%,#ffe8c8 46%,#ffc798 100%);position:relative;overflow:hidden;padding:32px 38px;box-shadow:var(--shadow)}.hero-copy{position:relative;z-index:2;max-width:380px}.hero-copy .tag{background:#fff9ed;color:#df7257;font-size:10px;font-weight:900;letter-spacing:1px;border-radius:20px;padding:8px 12px;display:inline-block}.hero-copy h1{font:900 clamp(34px,4.2vw,55px)/.99 Nunito,sans-serif;letter-spacing:-1.8px;margin:17px 0 10px;max-width:350px}.hero-copy p{color:#896951;font-size:14px;line-height:1.55;max-width:280px}.primary-btn,.secondary-btn{border:0;border-radius:15px;padding:14px 22px;font:900 14px Nunito,sans-serif;cursor:pointer;transition:transform .15s,filter .15s}.primary-btn{background:var(--coral);color:white;box-shadow:0 5px 0 #d64f42,0 8px 18px #e3634a40}.primary-btn:hover,.secondary-btn:hover{transform:translateY(-2px);filter:brightness(1.03)}.primary-btn:active,.secondary-btn:active{transform:translateY(2px);box-shadow:none}.hero-scene{position:absolute;right:4%;bottom:0;width:54%;height:100%;display:flex;align-items:end;justify-content:center}.hero-scene:before{content:'';position:absolute;bottom:20px;width:90%;height:195px;border-radius:50% 50% 0 0;background:#f9b273}.cafe-building{z-index:1;position:absolute;bottom:24px;width:75%;height:215px;border-radius:22px 22px 0 0;background:#fff6e9;border:8px solid #fff9f0;box-shadow:0 7px 0 #e7a06c}.awning{position:absolute;top:31px;left:-9px;right:-9px;height:45px;background:repeating-linear-gradient(90deg,#ff7963 0 42px,#fff4e5 42px 84px);border:4px solid white;border-radius:10px;box-shadow:0 4px 0 #e4a77b}.sign{position:absolute;top:0;left:50%;transform:translateX(-50%);white-space:nowrap;background:#fff3dc;border-radius:12px;padding:8px 16px;font:900 13px Nunito;color:#bd654d}.window{position:absolute;top:92px;left:12%;width:40%;height:76px;border:7px solid #e8a376;border-radius:11px;background:linear-gradient(135deg,#a4e8d2,#d3f5e7);font-size:42px;text-align:center}.door{position:absolute;top:84px;right:13%;width:29%;height:115px;border:6px solid #e8a376;border-bottom:0;border-radius:15px 15px 0 0;background:#b9e8d4;display:grid;place-items:center;font-size:38px}.plant{position:absolute;z-index:2;bottom:19px;right:5%;font-size:44px}.hero-burger{position:absolute;z-index:3;right:6%;top:12%;font-size:44px;transform:rotate(12deg);filter:drop-shadow(0 5px 3px #8e512333);animation:bob 3s ease-in-out infinite}.spark{position:absolute;z-index:3;font-size:22px;animation:bob 2s ease-in-out infinite}.spark.one{right:38%;top:17%}.spark.two{right:0;top:42%;animation-delay:.7s}@keyframes bob{50%{transform:translateY(-8px) rotate(4deg)}}.side-stack{display:flex;flex-direction:column;gap:16px}.level-card,.daily-card,.panel-card{background:white;border:1px solid #f4ece3;border-radius:22px;padding:20px;box-shadow:var(--shadow)}.level-card{background:#fff;border-top:5px solid var(--orange)}.level-head{display:flex;justify-content:space-between;align-items:center}.level-badge{background:#fff0d0;border-radius:10px;color:#bd8038;font-size:10px;font-weight:900;padding:7px 9px}.level-card h3,.daily-card h3{margin:12px 0 3px;font:900 19px Nunito}.level-card p,.daily-card p{color:var(--muted);font-size:12px;margin:0 0 15px}.level-progress{height:9px;border-radius:9px;background:#f5eee7;overflow:hidden;margin:12px 0 6px}.level-progress i{height:100%;display:block;background:linear-gradient(90deg,#ffbb55,#ff805c);border-radius:8px}.progress-caption{display:flex;justify-content:space-between;font-size:10px;color:#a8998e;font-weight:800}.level-card .primary-btn{width:100%;margin-top:17px;padding:12px}.daily-card{background:#e9f8ed;display:flex;align-items:center;gap:12px;padding:15px 17px}.daily-icon{font-size:35px}.daily-card h3{font-size:14px;margin:0 0 2px}.daily-card p{font-size:11px;margin:0}.stats-row{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:19px}.stat-card{background:#fff;border:1px solid #f3ece4;border-radius:18px;padding:15px 18px;display:flex;gap:12px;align-items:center}.stat-icon{width:39px;height:39px;border-radius:13px;background:#fff2dc;display:grid;place-items:center;font-size:20px}.stat-card b{display:block;font:900 17px Nunito}.stat-card small{color:#a3978d;font-size:10px;font-weight:700}.game-screen{padding-top:2px}.game-topline{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.game-level{display:flex;align-items:center;gap:12px}.round-back{border:0;background:#fff;border-radius:12px;width:40px;height:40px;box-shadow:var(--shadow);font-size:19px;cursor:pointer}.game-title{font:900 20px Nunito}.game-subtitle{font-size:10px;color:#aa9b90;font-weight:700}.goal-pill{padding:10px 14px;background:white;border-radius:15px;box-shadow:var(--shadow);font-size:12px;font-weight:900}.goal-pill span{color:#b79458}.progress-meter{height:9px;background:#eee3d7;border-radius:9px;overflow:hidden;width:180px;margin-top:6px}.progress-meter i{height:100%;display:block;background:linear-gradient(90deg,#71cb8d,#42ad78);border-radius:9px;transition:width .3s}.rush-board{background:#d9f3e8;border-radius:27px;position:relative;height:min(47vh,350px);min-height:270px;overflow:hidden;border:8px solid white;box-shadow:var(--shadow)}.board-sky{position:absolute;inset:0 0 35%;background:linear-gradient(#bfeee4,#e1f7e9)}.board-sky:after{content:'';position:absolute;bottom:-30px;left:-5%;width:110%;height:75px;border-radius:50%;background:#f8efd9}.string-lights{position:absolute;top:13px;left:0;right:0;text-align:center;font-size:18px;letter-spacing:22px;color:#f4b65c}.restaurant-sign{position:absolute;left:50%;top:35px;transform:translateX(-50%);background:#fff8eb;padding:7px 18px;border-radius:10px;color:#bd7354;font:900 12px Nunito;box-shadow:0 4px #e9c69e}.board-plants{position:absolute;bottom:77px;left:14px;font-size:33px}.board-plants.right{left:auto;right:14px}.queue{position:absolute;z-index:2;left:5%;right:5%;bottom:58px;display:flex;justify-content:center;align-items:end;gap:clamp(7px,3vw,27px);height:178px}.customer{position:relative;width:clamp(67px,11vw,105px);height:158px;flex-shrink:1;animation:arrive .4s ease both}.customer:nth-child(even){animation-delay:.1s}.customer .head{height:83px;width:76px;max-width:100%;margin:auto;border-radius:43% 43% 40% 40%;position:relative;border:4px solid #fff4e5;box-shadow:0 5px 0 #bd9678;font-size:42px;display:grid;place-items:center;z-index:1}.customer .body{height:79px;width:90%;margin:-5px auto 0;border-radius:25px 25px 12px 12px;border:4px solid #fff4e5;box-shadow:0 5px 0 #bd9678;font-size:28px;display:grid;place-items:center}.customer .order-bubble{position:absolute;right:-9px;top:-28px;background:white;border-radius:12px;padding:5px 7px;font-size:20px;box-shadow:0 3px 9px #51413a20;white-space:nowrap;z-index:3}.customer .order-bubble:after{content:'';position:absolute;bottom:-5px;left:12px;width:10px;height:10px;background:white;transform:rotate(45deg)}.patience{position:absolute;z-index:4;bottom:-13px;left:8%;width:84%;height:8px;border-radius:8px;background:#efe4d9;overflow:hidden}.patience i{height:100%;display:block;background:#62c77f;border-radius:8px;transition:width .3s}.patience.low i{background:#ff735b}.customer.vip:after{content:'VIP';position:absolute;top:-20px;left:50%;transform:translateX(-50%);background:#fbd774;color:#755229;font-size:8px;font-weight:900;padding:3px 6px;border-radius:8px}.counter{position:absolute;bottom:0;height:68px;background:linear-gradient(#bf8159,#a96342);left:0;right:0;border-top:8px solid #e6aa73;display:flex;align-items:center;justify-content:center;gap:10px}.counter span{width:58px;height:31px;border-radius:9px;background:#ffe7bd;display:grid;place-items:center;font-size:20px;box-shadow:0 3px #d59860}.empty-queue{align-self:center;background:#fff9e8;border-radius:15px;padding:13px 20px;color:#a48966;font-weight:800;font-size:13px}.stations{display:grid;grid-template-columns:repeat(4,1fr);gap:11px;margin-top:14px}.station{border:0;border-radius:17px;min-height:99px;background:white;box-shadow:0 5px 0 #eee4da,0 8px 20px #4f34200c;padding:10px;position:relative;cursor:pointer;color:var(--ink);transition:transform .15s,box-shadow .15s}.station:hover{transform:translateY(-3px)}.station:active{transform:translateY(3px);box-shadow:0 1px #eee4da}.station .food-icon{font-size:31px;display:block}.station b{display:block;font:900 12px Nunito;margin-top:1px}.station small{color:#a3958a;font-size:9px;font-weight:700}.station.ready{background:#edfaee;box-shadow:0 5px 0 #b8e4bf}.station.cooking{background:#fff6e8}.station .cook-timer{position:absolute;bottom:0;left:0;height:5px;background:#ffaa4f;border-radius:5px;transition:width .2s}.station .count-dot{position:absolute;top:7px;right:8px;border-radius:10px;background:#ff725a;color:white;padding:2px 6px;font-size:10px;font-weight:900}.action-row{display:flex;align-items:center;justify-content:space-between;margin-top:14px;gap:12px}.tray{background:#fff;border:1px dashed #e6c6a9;border-radius:15px;min-height:51px;flex:1;padding:6px 12px;display:flex;align-items:center;gap:7px}.tray-label{font-size:9px;color:#a19286;font-weight:900;letter-spacing:1px}.tray-items{display:flex;gap:5px;align-items:center;flex:1}.tray-item{border:0;border-radius:9px;background:#fff2db;padding:5px 8px;font-size:17px;cursor:pointer;position:relative}.tray-item small{font-size:8px;position:absolute;right:-3px;top:-5px;background:#ff715b;color:white;border-radius:8px;padding:1px 3px}.serve-btn{height:51px;padding:0 25px}.serve-btn:disabled{background:#c9c1bb;box-shadow:0 4px #aaa19a;cursor:not-allowed;filter:none;transform:none}.timer-note{font-size:10px;color:#aa9c91;margin-top:7px;text-align:center}.screen-heading{display:flex;justify-content:space-between;align-items:end;margin-bottom:20px}.map-track{di