dding:27px;box-shadow:0 20px 70px #35211855;text-align:center;position:relative}.modal-close{position:absolute;right:15px;top:14px;background:white;border:0;border-radius:50%;width:33px;height:33px;font-size:19px;cursor:pointer}.modal-art{font-size:55px}.modal h2{font:900 26px Nunito;margin:7px 0}.modal p{color:#998a7e;font-size:13px;line-height:1.55}.result-stars{font-size:35px;color:#f2b743;margin:5px}.result-summary{background:#fff1d7;border-radius:15px;padding:13px;margin:15px 0;font-weight:800}.modal .primary-btn{min-width:180px}.toast{position:fixed;z-index:40;bottom:30px;left:50%;transform:translate(-50%,20px);background:#392b32;color:white;padding:12px 18px;border-radius:14px;font-weight:800;font-size:12px;opacity:0;pointer-events:none;transition:.25s;box-shadow:var(--shadow);white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.pause-btn{border:0;background:#fff;border-radius:11px;padding:10px 13px;box-shadow:var(--shadow);font-weight:900;cursor:pointer}.empty-hint{padding:45px 20px;text-align:center;background:white;border-radius:20px;color:#9b8c81}
