(() => {
  const $ = (s, root=document) => root.querySelector(s);
  const app = $('#app'), modalRoot = $('#modal-root'), toastEl = $('#toast');
  const saveKey = 'restaurant-rush-save-v1';
  const defaults = {coins:120,gems:8,unlocked:1,stars:{},upgrades:{speed:0,quality:0,patience:0,storage:0},decor:0,served:0};
  let save = {...defaults,...JSON.parse(localStorage.getItem(saveKey)||'{}')};
  save.upgrades = {...defaults.upgrades,...save.upgrades};
  save.stars = save.stars || {};
  let currentScreen='home', game=null, toastTimer;
  const recipeIcons={Burger:'🍔',Fries:'🍟',Soda:'🥤',Shake:'🥤'};
  const customerTypes=[
    {name:'Regular',face:'👨🏻',shirt:'#82c9a6',patience:1,tip:1},
    {name:'Regular',face:'👩🏽',shirt:'#f39c91',patience:1,tip:1},
    {name:'Impatient',face:'👨🏾',shirt:'#b39adf',patience:.72,tip:.8},
    {name:'VIP',face:'👩🏼',shirt:'#f2bd54',patience:1.15,tip:2.1},
    {name:'Regular',face:'👨🏼‍🦰',shirt:'#79b9e8',patience:1.08,tip:1.2},
    {name:'Impatient',face:'👩🏻‍🦰',shirt:'#ee8ac1',patience:.75,tip:.8}
  ];
  const menu=['Burger','Fries','Soda','Shake'];
  const recipes={Burger:{icon:'🍔',duration:3600},Fries:{icon:'🍟',duration:2800},Soda:{icon:'🥤',duration:0},Shake:{icon:'🥤',duration:2100}};
  const levelData=n=>({goal:100+(n-1)*35,customers:7+Math.min(n,6),duration:82-Math.min(n-1,5)*4,complexity:Math.min(1+Math.floor((n-1)/2),3)});
  function persist(){localStorage.setItem(saveKey,JSON.stringify(save));updateWallet()}
  function updateWallet(){$('#coin-count').textContent=save.coins;$('#gem-count').textContent=save.gems}
