1: // Start gameplay once without guessing between multiple controls or following links.
2: export async function startForCapture(page, { enabled = true, selector = '', timeout = 3000 } = {}) {
3:   if (!enabled) return { clicked: false, reason: 'disabled' }
4:   const candidate = selector
5:     ? page.locator(selector)
6:     : page.locator('button, input[type="button"], input[type="submit"], [role="button"]')
7:   const deadline = Date.now() + timeout
8:   do {
9:     const matches = []
10:     for (const control of await candidate.all()) {
11:       if (!await control.isVisible() || !await control.isEnabled()) continue
12:       const eligible = await control.evaluate((element, explicit) => {
13:         if (element.closest('a[href], form') || element.getAttribute('aria-disabled') === 'true') return false
14:         if (explicit) return true
15:         const label = element.getAttribute('aria-label') || element.value || element.textContent || ''
16:         return /^(?:start|play)(?:\s+(?:game|now))?$/i.test(label.trim())
17:       }, Boolean(selector))
18:       if (eligible) matches.push(control)
19:     }
20:     if (matches.length > 1) return { clicked: false, reason: 'ambiguous' }
21:     if (matches.length === 1) {
22:       try { await matches[0].click({ trial: true, timeout: 2000 }) }
23:       catch (error) {
24:         if (error.name === 'TimeoutError') return { clicked: false, reason: 'not-actionable' }
25:         throw error
26:       }
27:       await matches[0].click({ timeout: 2000, noWaitAfter: true })
28:       return { clicked: true }
29:     }
30:     if (Date.now() >= deadline) break
31:     await page.waitForTimeout(Math.min(200, Math.max(0, deadline - Date.now())))
32:   } while (Date.now() <= deadline)
33:   return { clicked: false, reason: 'not-found' }
34: }

